// ============================================================
// MARKET HOURS CHECK
// ============================================================
// Verify the market is open. Skip US market holidays.
// This runs at 10:30 AM ET so time check is a safety net.
// Primary gate: holiday calendar check.
// ============================================================

const now = new Date();
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const etDate = new Date(etString);
const hours = etDate.getHours();
const minutes = etDate.getMinutes();
const month = etDate.getMonth() + 1;
const day = etDate.getDate();
const dayOfWeek = etDate.getDay();
const year = etDate.getFullYear();
const dateStr = `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;

// Weekend check
if (dayOfWeek === 0 || dayOfWeek === 6) {
  return [];
}

// US Market Holidays 2026 (NYSE closed)
// Update this list annually
const holidays2026 = [
  '2026-01-01', // New Year's Day
  '2026-01-19', // MLK Jr. Day
  '2026-02-16', // Presidents' Day
  '2026-04-03', // Good Friday
  '2026-05-25', // Memorial Day
  '2026-06-19', // Juneteenth
  '2026-07-03', // Independence Day (observed)
  '2026-09-07', // Labor Day
  '2026-11-26', // Thanksgiving
  '2026-12-25', // Christmas
];

if (holidays2026.includes(dateStr)) {
  return [];
}

// Market hours check (safety net — trigger is set to 10:30 AM)
const timeInMinutes = hours * 60 + minutes;
const MARKET_OPEN = 9 * 60 + 30;  // 9:30 AM
const MARKET_CLOSE = 16 * 60;      // 4:00 PM

if (timeInMinutes < MARKET_OPEN || timeInMinutes >= MARKET_CLOSE) {
  return [];
}

return [{
  json: {
    marketOpen: true,
    timestamp: now.toISOString(),
    etTime: `${hours}:${String(minutes).padStart(2, '0')}`,
    dateStr: dateStr,
    scanType: 'CSP_DAILY'
  }
}];

// ============================================================
// FUNDAMENTAL QUALITY SCREEN
// ============================================================
// For each ticker in the universe:
//   1. Price above 50-day SMA (bullish trend)
//   2. Not severely overbought (changesPercentage < +8% today)
//   3. Market cap > $50B (all in universe pass this)
//   4. Volume is reasonable (not halted / illiquid)
//
// Outputs: qualifying tickers with quote data attached
// ============================================================

// Safe helper to get data from referenced nodes
function safeGetNodeData(nodeName) {
  try {
    const nodeData = $(nodeName);
    if (nodeData && nodeData.first()) {
      return nodeData.first().json;
    }
  } catch (e) {
    // Node hasn't been executed
  }
  return null;
}

// Get data from all upstream nodes
const quotes = safeGetNodeData('FMP: Universe Quotes (11 Tickers)');
const vixData = safeGetNodeData('FMP: VIX & SPY Quote');
const triggerData = safeGetNodeData('Market Hours Check');

// Validate required data is present
if (!quotes) {
  throw new Error('Missing data from FMP: Universe Quotes node. Please execute the full workflow from the beginning or ensure both HTTP request nodes have completed.');
}

if (!vixData) {
  throw new Error('Missing data from FMP: VIX & SPY Quote node. Please execute the full workflow from the beginning.');
}

if (!triggerData) {
  throw new Error('Missing data from Market Hours Check node. Please execute the full workflow from the beginning.');
}

const quotesArray = Array.isArray(quotes) ? quotes : [quotes];
const vixArray = Array.isArray(vixData) ? vixData : [vixData];

// Extract VIX value
const vixQuote = vixArray.find(q => q.symbol === '^VIX' || q.symbol === 'VIX');
const vix = vixQuote ? vixQuote.price : 20; // default to 20 if unavailable

// Determine VIX regime and sizing adjustment
let regime, sizingPct;
if (vix < 15) {
  regime = 'LOW';
  sizingPct = 75;
} else if (vix <= 25) {
  regime = 'NORMAL';
  sizingPct = 100;
} else if (vix <= 35) {
  regime = 'ELEVATED';
  sizingPct = 50;
} else {
  regime = 'CRISIS';
  sizingPct = 25;
}

// Sector mapping
const SECTORS = {
  'AAPL': 'Technology',
  'MSFT': 'Technology',
  'GOOGL': 'Technology',
  'AMZN': 'Technology',
  'AVGO': 'Technology',
  'META': 'Technology',
  'NVDA': 'Technology',
  'V': 'Financial',
  'MA': 'Financial',
  'COST': 'Consumer Defensive',
  'SPY': 'Index'
};

// Quality screen
const qualifying = [];
const rejected = [];

for (const q of quotesArray) {
  const ticker = q.symbol;
  const reasons = [];

  // 1. Price above 50-day SMA
  if (q.priceAvg50 && q.price < q.priceAvg50) {
    reasons.push(`Below 50-day SMA ($${q.price.toFixed(2)} < $${q.priceAvg50.toFixed(2)})`);
  }

  // 2. Not severely overbought (single-day spike > 8%)
  if (q.changesPercentage && q.changesPercentage > 8) {
    reasons.push(`Overbought today (+${q.changesPercentage.toFixed(1)}%)`);
  }

  // 3. Volume sanity (skip if volume is 0 or halted)
  if (!q.volume || q.volume < 100000) {
    reasons.push(`Low/no volume (${q.volume || 0})`);
  }

  if (reasons.length === 0) {
    qualifying.push({
      ticker: ticker,
      price: q.price,
      priceAvg50: q.priceAvg50,
      priceAvg200: q.priceAvg200,
      changesPercentage: q.changesPercentage,
      volume: q.volume,
      avgVolume: q.avgVolume,
      marketCap: q.marketCap,
      yearHigh: q.yearHigh,
      yearLow: q.yearLow,
      sector: SECTORS[ticker] || 'Unknown'
    });
  } else {
    rejected.push({ ticker, reasons });
  }
}

return [{
  json: {
    qualifying,
    rejected,
    qualifyingCount: qualifying.length,
    rejectedCount: rejected.length,
    vix,
    regime,
    sizingPct,
    dateStr: triggerData.dateStr,
    timestamp: triggerData.timestamp
  }
}];

// ============================================================
// FILTER EARNINGS CONFLICTS
// ============================================================
// Remove tickers with earnings within the next 45 days
// (matches our max DTE target). Selling puts into earnings
// carries binary event risk — we avoid it entirely.
// ============================================================

const screenData = $('Fundamental Quality Screen').first().json;
const earningsRaw = $('FMP: Earnings Calendar (Next 45 Days)').first().json;

const earningsArray = Array.isArray(earningsRaw) ? earningsRaw : [];
const UNIVERSE = ['AAPL','MSFT','GOOGL','AMZN','AVGO','COST','V','MA','META','NVDA','SPY'];

// Build set of tickers reporting within 45 days
const earningsTickers = new Set();
const earningsDetails = {};

for (const e of earningsArray) {
  if (UNIVERSE.includes(e.symbol)) {
    earningsTickers.add(e.symbol);
    earningsDetails[e.symbol] = {
      date: e.date,
      epsEstimated: e.epsEstimated,
      revenueEstimated: e.revenueEstimated
    };
  }
}

// Filter qualifying tickers — remove those with upcoming earnings
const cleared = [];
const earningsExcluded = [];

for (const q of screenData.qualifying) {
  if (earningsTickers.has(q.ticker)) {
    earningsExcluded.push({
      ticker: q.ticker,
      earningsDate: earningsDetails[q.ticker].date,
      reason: `Earnings on ${earningsDetails[q.ticker].date} — within DTE window`
    });
  } else {
    cleared.push(q);
  }
}

return [{
  json: {
    cleared,
    earningsExcluded,
    clearedCount: cleared.length,
    excludedCount: earningsExcluded.length,
    vix: screenData.vix,
    regime: screenData.regime,
    sizingPct: screenData.sizingPct,
    rejected: screenData.rejected,
    dateStr: screenData.dateStr,
    timestamp: screenData.timestamp
  }
}];

// ============================================================
// FETCH OPTIONS CHAINS
// ============================================================
// For each cleared ticker, fetch put options chain.
// Primary: Massive.com API
// Fallback: FMP /v4/options-chain/{TICKER}
//
// Filters at fetch time:
//   - option_type: put
//   - strike range: 85%-97% of current price (OTM puts)
// ============================================================

const data = $('Filter Earnings Conflicts').first().json;
const cleared = data.cleared;

if (!cleared || cleared.length === 0) {
  return [{
    json: {
      chains: [],
      chainCount: 0,
      vix: data.vix,
      regime: data.regime,
      sizingPct: data.sizingPct,
      earningsExcluded: data.earningsExcluded,
      rejected: data.rejected,
      dateStr: data.dateStr,
      timestamp: data.timestamp
    }
  }];
}

const MASSIVE_API_KEY = 'kEnhZTIYm_UZZSfpSPuYQgsW_kG0vPHp';
const FMP_API_KEY = 'FAAjnYQTvfGg8j7RoPSvHYRVtSKTvJyz';

const chains = [];

for (const ticker of cleared) {
  const strikeMin = Math.floor(ticker.price * 0.85);
  const strikeMax = Math.ceil(ticker.price * 0.97);

  let contracts = [];
  let source = '';

  // --- Attempt 1: Massive.com API ---
  try {
    const massiveUrl = `https://api.massive.com/v1/options/chain/${ticker.ticker}?option_type=put&strike_min=${strikeMin}&strike_max=${strikeMax}`;
    const massiveResp = await fetch(massiveUrl, {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${MASSIVE_API_KEY}`,
        'Content-Type': 'application/json'
      },
      signal: AbortSignal.timeout(8000)
    });

    if (massiveResp.ok) {
      const massiveData = await massiveResp.json();
      // Massive.com returns data in .options or .data array
      const options = massiveData.options || massiveData.data || massiveData;
      if (Array.isArray(options) && options.length > 0) {
        contracts = options;
        source = 'massive';
      }
    }
  } catch (err) {
    // Massive failed — try fallback
  }

  // --- Attempt 2: FMP Fallback ---
  if (contracts.length === 0) {
    try {
      const fmpUrl = `https://financialmodelingprep.com/api/v4/options-chain/${ticker.ticker}?apikey=${FMP_API_KEY}`;
      const fmpResp = await fetch(fmpUrl, {
        method: 'GET',
        signal: AbortSignal.timeout(8000)
      });

      if (fmpResp.ok) {
        const fmpData = await fmpResp.json();
        // FMP returns all options — filter to puts in strike range
        const filtered = (Array.isArray(fmpData) ? fmpData : []).filter(o => {
          const isPut = (o.type === 'put' || o.putCall === 'put' || o.side === 'put');
          const inRange = o.strike >= strikeMin && o.strike <= strikeMax;
          return isPut && inRange;
        });
        contracts = filtered;
        source = 'fmp';
      }
    } catch (err) {
      // Both APIs failed for this ticker
      source = 'failed';
    }
  }

  chains.push({
    ticker: ticker.ticker,
    price: ticker.price,
    sector: ticker.sector,
    priceAvg50: ticker.priceAvg50,
    yearHigh: ticker.yearHigh,
    yearLow: ticker.yearLow,
    contracts: contracts,
    contractCount: contracts.length,
    source: source
  });
}

return [{
  json: {
    chains,
    chainCount: chains.length,
    vix: data.vix,
    regime: data.regime,
    sizingPct: data.sizingPct,
    earningsExcluded: data.earningsExcluded,
    rejected: data.rejected,
    dateStr: data.dateStr,
    timestamp: data.timestamp
  }
}];

// ============================================================
// FETCH FULL CHAINS (INSTITUTIONAL)
// ============================================================
// Fetches both calls and puts (20-60 DTE) per cleared ticker
// for P/C ratio, UOA, IV skew, GEX. Uses Massive.com v3 API.
// ============================================================

const data = $('Filter Earnings Conflicts').first().json;
const cleared = data.cleared || [];

if (!cleared.length) {
  return [{ json: { fullChains: [], tickerSignals: {}, vix: data.vix, regime: data.regime, sizingPct: data.sizingPct, dateStr: data.dateStr } }];
}

const MASSIVE_API_KEY = 'kEnhZTIYm_UZZSfpSPuYQgsW_kG0vPHp';
const today = new Date();
const fromDate = new Date(today);
fromDate.setDate(fromDate.getDate() + 20);
const toDate = new Date(today);
toDate.setDate(toDate.getDate() + 60);
const fromStr = fromDate.toISOString().split('T')[0];
const toStr = toDate.toISOString().split('T')[0];

const fullChains = [];

for (const t of cleared) {
  let calls = [];
  let puts = [];
  try {
    const [callResp, putResp] = await Promise.all([
      fetch(`https://api.massive.com/v3/snapshot/options/${t.ticker}?contract_type=call&expiration_date.gte=${fromStr}&expiration_date.lte=${toStr}&limit=250`, {
        headers: { 'Authorization': `Bearer ${MASSIVE_API_KEY}`, 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(12000)
      }),
      fetch(`https://api.massive.com/v3/snapshot/options/${t.ticker}?contract_type=put&expiration_date.gte=${fromStr}&expiration_date.lte=${toStr}&limit=250`, {
        headers: { 'Authorization': `Bearer ${MASSIVE_API_KEY}`, 'Content-Type': 'application/json' },
        signal: AbortSignal.timeout(12000)
      })
    ]);
    if (callResp.ok) {
      const j = await callResp.json();
      calls = j.results || [];
    }
    if (putResp.ok) {
      const j = await putResp.json();
      puts = j.results || [];
    }
  } catch (e) {}
  fullChains.push({
    ticker: t.ticker,
    price: t.price,
    calls,
    puts
  });
}

return [{
  json: {
    fullChains,
    vix: data.vix,
    regime: data.regime,
    sizingPct: data.sizingPct,
    dateStr: data.dateStr,
    timestamp: data.timestamp
  }
}];

// ============================================================
// INSTITUTIONAL SIGNALS
// ============================================================
// Computes: P/C ratio (vol, OI, $), UOA, IV skew (25Δ), GEX,
// Net Sentiment (-100 to +100), Liquidity 1-10, Confidence adj,
// Regime-specific strategy. See reference/institutional-signals-spec.md
// ============================================================

const data = $('Fetch Full Chains (Institutional)').first().json;
const fullChains = data.fullChains || [];
const vix = data.vix ?? 20;
const regime = data.regime || 'NORMAL';

function norm(c, type) {
  const det = c.details || {};
  const g = c.greeks || {};
  const q = c.last_quote || {};
  const strike = det.strike_price ?? c.strike;
  const bid = q.bid ?? c.bid ?? 0;
  const ask = q.ask ?? c.ask ?? 0;
  const mid = (bid + ask) / 2 || 0;
  const vol = (c.day && c.day.volume) ?? c.volume ?? 0;
  const oi = c.open_interest ?? c.openInterest ?? 0;
  const iv = c.implied_volatility ?? c.impliedVolatility ?? null;
  const delta = g.delta ?? c.delta;
  const gamma = g.gamma ?? c.gamma ?? 0;
  return { type, strike, bid, ask, mid, volume: vol, openInterest: oi, iv, delta, gamma, expiration: det.expiration_date || c.expiration };
}

function calcDTE(exp) {
  if (!exp) return null;
  const e = new Date(exp);
  return Math.ceil((e - new Date()) / (1000 * 60 * 60 * 24));
}

const BLOCK_NOTIONAL = 100000;
const UOA_VOL_OI_RATIO = 2;

const tickerSignals = {};

for (const fc of fullChains) {
  const ticker = fc.ticker;
  const spot = fc.price || 1;
  const calls = (fc.calls || []).map(c => norm(c, 'call'));
  const puts = (fc.puts || []).map(c => norm(c, 'put'));

  const callVol = calls.reduce((s, c) => s + (c.volume || 0), 0);
  const putVol = puts.reduce((s, p) => s + (p.volume || 0), 0);
  const callOI = calls.reduce((s, c) => s + (c.openInterest || 0), 0);
  const putOI = puts.reduce((s, p) => s + (p.openInterest || 0), 0);
  const callDollar = calls.reduce((s, c) => s + (c.mid || 0) * 100 * (c.volume || 0), 0);
  const putDollar = puts.reduce((s, p) => s + (p.mid || 0) * 100 * (p.volume || 0), 0);

  const putCallRatioVol = callVol > 0 ? putVol / callVol : (putVol > 0 ? 2 : 1);
  const putCallRatioOI = callOI > 0 ? putOI / callOI : (putOI > 0 ? 2 : 1);
  const putCallRatioDollar = callDollar > 0 ? putDollar / callDollar : (putDollar > 0 ? 2 : 1);

  let unusualCount = 0;
  let largeBlocks = 0;
  const allContracts = [...calls, ...puts];
  for (const c of allContracts) {
    const vol = c.volume || 0;
    const oi = Math.max(c.openInterest || 0, 1);
    if (vol >= UOA_VOL_OI_RATIO * oi) unusualCount++;
    const notional = (c.mid || 0) * 100 * vol;
    if (notional >= BLOCK_NOTIONAL) largeBlocks++;
  }

  let putIV25 = null;
  let callIV25 = null;
  const puts25 = puts.filter(p => p.delta != null && Math.abs(p.delta + 0.25) < 0.05);
  const calls25 = calls.filter(c => c.delta != null && Math.abs(c.delta - 0.25) < 0.05);
  if (puts25.length) putIV25 = puts25.reduce((s, p) => s + (p.iv ?? 0), 0) / puts25.length;
  if (calls25.length) callIV25 = calls25.reduce((s, c) => s + (c.iv ?? 0), 0) / calls25.length;
  let ivSkew25 = null;
  if (putIV25 != null && callIV25 != null && callIV25 > 0) ivSkew25 = putIV25 / callIV25;

  let totalGEX = 0;
  let maxGEXStrike = null;
  let maxGEX = 0;
  for (const c of allContracts) {
    const gamma = c.gamma ?? 0;
    const oi = c.openInterest ?? 0;
    const gex = gamma * oi * 100 * (spot * spot) * (c.type === 'put' ? 1 : -1);
    totalGEX += gex;
    if (Math.abs(gex) > maxGEX) {
      maxGEX = Math.abs(gex);
      maxGEXStrike = c.strike;
    }
  }

  const sentimentFromPC = putCallRatioVol > 1.2 ? -30 : putCallRatioVol < 0.8 ? 30 : 0;
  const sentimentFromSkew = ivSkew25 != null && ivSkew25 > 1.2 ? -20 : ivSkew25 != null && ivSkew25 < 0.9 ? 15 : 0;
  const sentimentFromUOA = unusualCount > 5 ? -15 : 0;
  const netSentiment = Math.max(-100, Math.min(100, Math.round(sentimentFromPC + sentimentFromSkew + sentimentFromUOA)));

  const avgSpreadPct = allContracts.filter(c => c.mid > 0).length
    ? allContracts.filter(c => c.mid > 0).reduce((s, c) => s + (Math.abs(c.ask - c.bid) / c.mid) * 100, 0) / Math.max(1, allContracts.filter(c => c.mid > 0).length)
    : 10;
  const maxOI = Math.max(...allContracts.map(c => c.openInterest || 0), 1);
  const maxVol = Math.max(...allContracts.map(c => c.volume || 0), 0);
  let liquidityScore = 5;
  if (avgSpreadPct < 5 && maxOI >= 500 && maxVol >= 50) liquidityScore = 9;
  else if (avgSpreadPct < 8 && maxOI >= 100) liquidityScore = 7;
  else if (avgSpreadPct > 15 || maxOI < 50) liquidityScore = 3;
  else liquidityScore = 5;
  liquidityScore = Math.max(1, Math.min(10, liquidityScore));

  let confidenceAdjustment = 0;
  if (netSentiment > 20) confidenceAdjustment = 3;
  else if (netSentiment < -20) confidenceAdjustment = -3;
  if (unusualCount > 3) confidenceAdjustment -= 1;

  const regimeStrategies = {
    LOW: 'Naked CSP / covered calls OK.',
    NORMAL: 'CSP, bull put spreads, covered calls.',
    ELEVATED: 'Prefer defined-risk spreads; reduce size.',
    CRISIS: 'Spreads only; minimal size; avoid naked options.'
  };
  const regimeStrategy = regimeStrategies[regime] || regimeStrategies.NORMAL;

  tickerSignals[ticker] = {
    putCallRatioVol: Math.round(putCallRatioVol * 100) / 100,
    putCallRatioOI: Math.round(putCallRatioOI * 100) / 100,
    putCallRatioDollar: Math.round(putCallRatioDollar * 100) / 100,
    unusualActivityCount: unusualCount,
    largeBlocksCount: largeBlocks,
    ivSkew25: ivSkew25 != null ? Math.round(ivSkew25 * 1000) / 1000 : null,
    gex: Math.round(totalGEX),
    maxGammaStrike: maxGEXStrike,
    netSentiment,
    liquidityScore1_10: liquidityScore,
    confidenceAdjustment,
    regimeStrategy
  };
}

return [{
  json: {
    tickerSignals,
    vix,
    regime,
    sizingPct: data.sizingPct,
    dateStr: data.dateStr
  }
}];

// ============================================================
// CSP OPPORTUNITY SCORER
// ============================================================
// For each options contract across all tickers:
//   1. FILTER: delta between -0.30 and -0.20, DTE 30-45,
//      bid > 0, open interest > 10
//   2. CALCULATE:
//      - Annualized return on capital = (premium / strike) * (365 / DTE)
//      - Breakeven = strike - premium
//      - Max loss per contract = (strike - premium) * 100
//   3. SCORE (weighted composite):
//      - Annualized return:   40%
//      - IV Rank proxy:       30%
//      - Liquidity (OI+vol):  20%
//      - Technical trend:     10%
//   4. SECTOR DIVERSIFICATION: max 3 tech positions
//   5. VIX REGIME sizing adjustment
//   6. OUTPUT: top 3 opportunities ranked by score
// ============================================================

const data = $('Fetch Options Chains').first().json;
const chains = data.chains || [];
const PORTFOLIO_VALUE = 100000;
const MAX_POSITION_PCT = 0.05; // 5% max per position
const MAX_SECTOR_POSITIONS = 3;
const MAX_SECTOR_EXPOSURE_PCT = 0.25; // 25%

// Calculate today for DTE
const today = new Date();

// Normalize contract data across Massive.com and FMP formats
function normalizeContract(c, source) {
  if (source === 'massive') {
    return {
      strike: c.strike || c.strikePrice,
      bid: c.bid || c.bidPrice || 0,
      ask: c.ask || c.askPrice || 0,
      delta: c.delta || c.greeks?.delta || null,
      gamma: c.gamma || c.greeks?.gamma || null,
      theta: c.theta || c.greeks?.theta || null,
      iv: c.impliedVolatility || c.iv || c.implied_volatility || null,
      openInterest: c.openInterest || c.open_interest || 0,
      volume: c.volume || c.totalVolume || 0,
      expiration: c.expiration || c.expirationDate || c.expiry,
      dte: c.dte || c.daysToExpiration || null
    };
  } else {
    // FMP format
    return {
      strike: c.strike || c.strikePrice,
      bid: c.bid || c.bidPrice || 0,
      ask: c.ask || c.askPrice || 0,
      delta: c.delta || c.greeks?.delta || null,
      gamma: c.gamma || c.greeks?.gamma || null,
      theta: c.theta || c.greeks?.theta || null,
      iv: c.impliedVolatility || c.iv || null,
      openInterest: c.openInterest || c.open_interest || 0,
      volume: c.volume || c.totalVolume || 0,
      expiration: c.expiration || c.expirationDate,
      dte: c.dte || c.daysToExpiration || null
    };
  }
}

// Calculate DTE from expiration date if not provided
function calcDTE(expiration) {
  if (!expiration) return null;
  const exp = new Date(expiration);
  const diffMs = exp.getTime() - today.getTime();
  return Math.ceil(diffMs / (1000 * 60 * 60 * 24));
}

// All scored opportunities
const allOpportunities = [];

for (const chain of chains) {
  if (!chain.contracts || chain.contracts.length === 0) continue;

  for (const raw of chain.contracts) {
    const c = normalizeContract(raw, chain.source);

    // Calculate DTE if missing
    const dte = c.dte || calcDTE(c.expiration);
    if (!dte) continue;

    // --- FILTER 1: DTE 30-45 ---
    if (dte < 30 || dte > 45) continue;

    // --- FILTER 2: Delta between -0.30 and -0.20 ---
    // Delta for puts is negative; handle both conventions
    const absDelta = Math.abs(c.delta || 0);
    if (absDelta < 0.20 || absDelta > 0.30) continue;

    // --- FILTER 3: Bid > 0 (tradeable) ---
    if (!c.bid || c.bid <= 0) continue;

    // --- FILTER 4: Minimum liquidity ---
    if ((c.openInterest || 0) < 10) continue;

    // --- CALCULATIONS ---
    const premium = c.bid; // conservative: use bid price
    const midPrice = (c.bid + c.ask) / 2;
    const strike = c.strike;
    const annualizedReturn = (premium / strike) * (365 / dte) * 100;
    const breakeven = strike - premium;
    const maxLossPerContract = (strike - premium) * 100;
    const collateralPerContract = strike * 100;

    // Max contracts by position sizing
    const maxAllocation = PORTFOLIO_VALUE * MAX_POSITION_PCT * (data.sizingPct / 100);
    const maxContracts = Math.floor(maxAllocation / collateralPerContract);
    if (maxContracts < 1) continue;

    // --- IV Rank proxy ---
    // Use IV relative to historical range as proxy
    // If IV data available, use it; otherwise estimate from premium richness
    let ivRankProxy = 50; // default middle
    if (c.iv) {
      // Rough IV rank: if IV > 0.40 that's high, < 0.15 that's low
      ivRankProxy = Math.min(100, Math.max(0, ((c.iv - 0.15) / (0.50 - 0.15)) * 100));
    } else {
      // Estimate from premium as % of strike
      const premiumPct = (premium / strike) * 100;
      ivRankProxy = Math.min(100, premiumPct * 15); // rough scaling
    }

    // Only proceed if IV Rank > 30% (we want to sell rich premium)
    if (ivRankProxy < 30) continue;

    // --- SCORING ---
    // Annualized return component (40%) — normalize 0-100 scale
    // 8% annual = 0, 40%+ annual = 100
    const returnScore = Math.min(100, Math.max(0, (annualizedReturn - 8) / (40 - 8) * 100));

    // IV Rank component (30%) — already 0-100
    const ivScore = ivRankProxy;

    // Liquidity component (20%)
    // OI > 1000 and volume > 100 = excellent
    const oiScore = Math.min(100, ((c.openInterest || 0) / 1000) * 50);
    const volScore = Math.min(100, ((c.volume || 0) / 100) * 50);
    const liquidityScore = (oiScore + volScore) / 2;

    // Technical trend component (10%)
    // Price above 50-day SMA = full points (already screened, so base 70)
    // Closer to 52-week high = stronger trend
    let trendScore = 70; // base for being above 50-SMA
    if (chain.yearHigh && chain.price) {
      const pctFromHigh = (chain.price / chain.yearHigh) * 100;
      trendScore = Math.min(100, pctFromHigh);
    }

    // Weighted composite
    const compositeScore = (
      returnScore * 0.40 +
      ivScore * 0.30 +
      liquidityScore * 0.20 +
      trendScore * 0.10
    );

    allOpportunities.push({
      ticker: chain.ticker,
      sector: chain.sector,
      currentPrice: chain.price,
      strike: strike,
      expiration: c.expiration,
      dte: dte,
      bid: premium,
      ask: c.ask,
      mid: midPrice,
      delta: c.delta,
      absDelta: absDelta,
      iv: c.iv,
      ivRankProxy: Math.round(ivRankProxy),
      theta: c.theta,
      openInterest: c.openInterest,
      volume: c.volume,
      annualizedReturn: Math.round(annualizedReturn * 100) / 100,
      breakeven: Math.round(breakeven * 100) / 100,
      maxLossPerContract: Math.round(maxLossPerContract),
      collateralPerContract: Math.round(collateralPerContract),
      maxContracts: maxContracts,
      totalPremium: Math.round(premium * maxContracts * 100),
      totalCollateral: Math.round(collateralPerContract * maxContracts),
      compositeScore: Math.round(compositeScore * 100) / 100,
      returnScore: Math.round(returnScore * 100) / 100,
      ivScore: Math.round(ivScore * 100) / 100,
      liquidityScore: Math.round(liquidityScore * 100) / 100,
      trendScore: Math.round(trendScore * 100) / 100,
      // Management levels
      profitTarget: Math.round(premium * 0.50 * 100) / 100, // close at 50% profit
      stopLoss: Math.round(premium * 2.00 * 100) / 100,     // stop at 200% of credit
      source: chain.source
    });
  }
}

// --- SECTOR DIVERSIFICATION CHECK ---
// Sort by score first
allOpportunities.sort((a, b) => b.compositeScore - a.compositeScore);

const sectorCount = {};
const sectorExposure = {};
const top3 = [];
const sectorWarnings = [];

for (const opp of allOpportunities) {
  if (top3.length >= 3) break;

  const sector = opp.sector;
  const currentSectorCount = sectorCount[sector] || 0;
  const currentSectorExp = sectorExposure[sector] || 0;
  const positionExposure = opp.totalCollateral / PORTFOLIO_VALUE;

  // Check sector position limit
  if (currentSectorCount >= MAX_SECTOR_POSITIONS) {
    sectorWarnings.push(`${opp.ticker}: Skipped — ${sector} already has ${MAX_SECTOR_POSITIONS} positions`);
    continue;
  }

  // Check sector exposure limit
  if (currentSectorExp + positionExposure > MAX_SECTOR_EXPOSURE_PCT) {
    sectorWarnings.push(`${opp.ticker}: Skipped — ${sector} exposure would exceed 25%`);
    continue;
  }

  // Accept this opportunity
  sectorCount[sector] = currentSectorCount + 1;
  sectorExposure[sector] = currentSectorExp + positionExposure;
  opp.rank = top3.length + 1;
  top3.push(opp);
}

// Calculate aggregate risk metrics
const totalCollateralDeployed = top3.reduce((sum, o) => sum + o.totalCollateral, 0);
const totalPremiumCollected = top3.reduce((sum, o) => sum + o.totalPremium, 0);
const cashAfterTrades = PORTFOLIO_VALUE - totalCollateralDeployed;
const cashPct = Math.round((cashAfterTrades / PORTFOLIO_VALUE) * 100);

return [{
  json: {
    top3,
    totalScanned: allOpportunities.length,
    sectorCount,
    sectorExposure,
    sectorWarnings,
    totalCollateralDeployed,
    totalPremiumCollected,
    cashAfterTrades,
    cashPct,
    vix: data.vix,
    regime: data.regime,
    sizingPct: data.sizingPct,
    earningsExcluded: data.earningsExcluded || [],
    rejected: data.rejected || [],
    dateStr: data.dateStr,
    portfolioValue: PORTFOLIO_VALUE
  }
}];

// ============================================================
// FORMAT TELEGRAM ALERT
// ============================================================
// Formats the top 3 CSP opportunities into a clean Telegram
// message with trade details, risk checks, and action items.
// ============================================================

const data = $('CSP Opportunity Scorer').first().json;
const top3 = data.top3 || [];

if (top3.length === 0) {
  // No opportunities found — send brief notification
  const noOppMsg = [
    `\u{1F4CA} CSP DAILY SCAN \u2014 ${data.dateStr}`,
    `VIX: ${data.vix.toFixed(1)} (${data.regime}) | Sizing: ${data.sizingPct}%`,
    '',
    '\u26A0\uFE0F No qualifying CSP opportunities today.',
    '',
    `Scanned: ${data.totalScanned || 0} contracts`,
  ];

  if (data.earningsExcluded && data.earningsExcluded.length > 0) {
    noOppMsg.push('');
    noOppMsg.push('Earnings exclusions:');
    for (const e of data.earningsExcluded) {
      noOppMsg.push(`  \u2022 ${e.ticker}: ${e.earningsDate}`);
    }
  }

  if (data.rejected && data.rejected.length > 0) {
    noOppMsg.push('');
    noOppMsg.push('Quality screen rejections:');
    for (const r of data.rejected) {
      noOppMsg.push(`  \u2022 ${r.ticker}: ${r.reasons.join(', ')}`);
    }
  }

  return [{ json: { text: noOppMsg.join('\n'), hasOpportunities: false } }];
}

// Medal icons
const medals = ['\u{1F947}', '\u{1F948}', '\u{1F949}'];

const lines = [
  `\u{1F4CA} CSP DAILY SCAN \u2014 ${data.dateStr}`,
  `VIX: ${data.vix.toFixed(1)} (${data.regime}) | Sizing: ${data.sizingPct}%`,
  `Scanned: ${data.totalScanned} contracts across ${data.sectorCount ? Object.keys(data.sectorCount).length : 0} sectors`,
  ''
];

for (let i = 0; i < top3.length; i++) {
  const o = top3[i];
  const medal = medals[i] || `#${i+1}`;

  lines.push(`${medal} #${i+1} ${o.ticker} $${o.strike}P ${o.expiration}`);
  lines.push(`  Credit: $${o.bid.toFixed(2)} | Delta: ${o.delta.toFixed(3)} | DTE: ${o.dte}`);
  lines.push(`  Annual Return: ${o.annualizedReturn}% | Breakeven: $${o.breakeven}`);
  lines.push(`  IV Rank: ${o.ivRankProxy}% | Sector: ${o.sector}`);
  lines.push(`  Score: ${o.compositeScore} (Ret:${o.returnScore} IV:${o.ivScore} Liq:${o.liquidityScore} Trend:${o.trendScore})`);
  lines.push(`  Contracts: ${o.maxContracts} | Premium: $${o.totalPremium} | Collateral: $${o.totalCollateral.toLocaleString()}`);
  lines.push(`  Manage: Close at $${o.profitTarget.toFixed(2)} (50%) | Stop at $${o.stopLoss.toFixed(2)} (200%)`);
  lines.push('');
}

lines.push('\u26A0\uFE0F Risk Checks:');

// Sector exposure
if (data.sectorExposure) {
  for (const [sector, exp] of Object.entries(data.sectorExposure)) {
    lines.push(`  \u2022 ${sector} exposure: ${(exp * 100).toFixed(1)}% (${data.sectorCount[sector]} positions)`);
  }
}

// Max position
const largestPosition = top3[0];
lines.push(`  \u2022 Max position: $${largestPosition.totalCollateral.toLocaleString()} (${((largestPosition.totalCollateral / data.portfolioValue) * 100).toFixed(1)}% of portfolio)`);
lines.push(`  \u2022 Total collateral: $${data.totalCollateralDeployed.toLocaleString()} (${((data.totalCollateralDeployed / data.portfolioValue) * 100).toFixed(1)}%)`);
lines.push(`  \u2022 Cash after trades: $${data.cashAfterTrades.toLocaleString()} (${data.cashPct}%)`);

// Sector warnings
if (data.sectorWarnings && data.sectorWarnings.length > 0) {
  lines.push('');
  lines.push('\u{1F6A8} Diversification notes:');
  for (const w of data.sectorWarnings) {
    lines.push(`  \u2022 ${w}`);
  }
}

// Earnings exclusions
if (data.earningsExcluded && data.earningsExcluded.length > 0) {
  lines.push('');
  lines.push('\u{1F4C5} Earnings exclusions:');
  for (const e of data.earningsExcluded) {
    lines.push(`  \u2022 ${e.ticker}: ${e.earningsDate}`);
  }
}

lines.push('');
lines.push('Use /paper-trade to log a trade.');

return [{ json: { text: lines.join('\n'), hasOpportunities: true, top3, dateStr: data.dateStr } }];

